-- Series 39 (multi-port, quote-only Price NULL). Run from file (SSMS: File > Open > Execute).
IF NOT EXISTS (SELECT 1 FROM Categories WHERE Name = N'Series 39')
    INSERT INTO Categories (Name, Description, BodyMaterial, SeatMaterial, Design, KeyFeatures)
    VALUES (N'Series 39',
        N'The Mars Series 39 is a 3-way threaded, direct-mount, SIL3-capable ball valve rated to 1000 PSI, in full or reduced port with L-port or T-port ball, sizes 1/4" to 2". CF8M body with PTFE/RTFE seats; NPT, BSP or BSPT ends.',
        N'CF8M', N'PTFE / RTFE', N'3-Way Threaded Direct Mount Ball Valve',
        N'3-way threaded direct mount design
SIL3 capable
Full port & reduced port
Ball configuration: L port, T port
Rated to 1000 PSI
CF8M body
PTFE / RTFE seats
Ends: NPT, BSP, BSPT
Size 1/4" to 2"');

DECLARE @SeriesName nvarchar(100) = N'Series 39';
DECLARE @CategoryId int = (SELECT CategoryId FROM Categories WHERE Name = @SeriesName);

INSERT INTO Filters (Name) SELECT v.Name FROM (VALUES (N'End Connection'),(N'Size'),(N'Ball Configuration'),(N'Port')) AS v(Name)
WHERE NOT EXISTS (SELECT 1 FROM Filters f WHERE f.Name = v.Name);

INSERT INTO CategoryFilters (CategoryId, FilterId, SortOrder)
SELECT @CategoryId, f.FilterId, v.SortOrder FROM (VALUES (N'End Connection',0),(N'Size',1),(N'Ball Configuration',2),(N'Port',3)) AS v(FilterName, SortOrder)
JOIN Filters f ON f.Name = v.FilterName WHERE NOT EXISTS (SELECT 1 FROM CategoryFilters cf WHERE cf.CategoryId=@CategoryId AND cf.FilterId=f.FilterId);

